#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh — Képesség-regisztráció és intelligens delegation.

Ez a modul implementálja:
  1. mesh_nodes.capabilities mező — minden node hirdeti a skilljeit
  2. Automatikus delegation: a legalkalmasabb agentnek route-ol (nem körben)
  3. Skill-sync: új skill tanulásakor peer-ek automatikusan megkapják
  4. P50/P95 latencia-grafikon transportonként
  5. DLQ (Dead Letter Queue) panel

Futtatható a repó gyökeréből:
    python capability_registration.py
"""

from __future__ import annotations

import heapq
import json
import logging
import statistics
import threading
import time
import uuid
from collections import defaultdict, deque
from dataclasses import dataclass, field, asdict
from enum import Enum
from typing import Any, Callable, Deque, Dict, List, Optional, Set, Tuple

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("a2a_mesh.capability")


# ---------------------------------------------------------------------------
# 1.  Adatmodellek
# ---------------------------------------------------------------------------

class Transport(str, Enum):
    HTTP = "http"
    WEBSOCKET = "websocket"
    GRPC = "grpc"
    INPROCESS = "inprocess"


@dataclass
class Capability:
    """Egyetlen skill leírása."""
    name: str
    version: str = "1.0.0"
    description: str = ""
    tags: List[str] = field(default_factory=list)
    confidence: float = 1.0          # 0.0 – 1.0, mennyire biztos a node a skillben
    cost: float = 1.0                # relatív végrehajtási költség
    learned_at: float = field(default_factory=time.time)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "Capability":
        return Capability(**d)


@dataclass
class LatencySample:
    transport: Transport
    latency_ms: float
    timestamp: float = field(default_factory=time.time)


@dataclass
class DeadLetter:
    id: str
    task_name: str
    target_node: str
    payload: Dict[str, Any]
    error: str
    attempts: int
    created_at: float = field(default_factory=time.time)
    last_attempt_at: float = field(default_factory=time.time)


@dataclass
class MeshNode:
    """Egy mesh node, amely hirdeti a képességeit."""
    node_id: str
    name: str
    address: str
    capabilities: List[Capability] = field(default_factory=list)
    online: bool = True
    last_heartbeat: float = field(default_factory=time.time)
    metadata: Dict[str, Any] = field(default_factory=dict)

    # ------------------------------------------------------------------
    # Capability helpers
    # ------------------------------------------------------------------
    def add_capability(self, cap: Capability) -> None:
        existing = {c.name for c in self.capabilities}
        if cap.name in existing:
            self.capabilities = [
                cap if c.name == cap.name else c for c in self.capabilities
            ]
        else:
            self.capabilities.append(cap)
        logger.info(
            "Node %s hirdeti a skillt: %s v%s (confidence=%.2f)",
            self.node_id, cap.name, cap.version, cap.confidence,
        )

    def remove_capability(self, name: str) -> None:
        self.capabilities = [c for c in self.capabilities if c.name != name]

    def has_capability(self, name: str) -> bool:
        return any(c.name == name for c in self.capabilities)

    def get_capability(self, name: str) -> Optional[Capability]:
        for c in self.capabilities:
            if c.name == name:
                return c
        return None

    def capability_names(self) -> List[str]:
        return [c.name for c in self.capabilities]

    def to_dict(self) -> Dict[str, Any]:
        return {
            "node_id": self.node_id,
            "name": self.name,
            "address": self.address,
            "capabilities": [c.to_dict() for c in self.capabilities],
            "online": self.online,
            "last_heartbeat": self.last_heartbeat,
            "metadata": self.metadata,
        }


# ---------------------------------------------------------------------------
# 2.  Latencia-mérő (P50/P95 transportonként)
# ---------------------------------------------------------------------------

class LatencyTracker:
    """P50/P95 latencia-mérés transportonként, csúszó ablakkal."""

    def __init__(self, window_size: int = 500) -> None:
        self._window_size = window_size
        self._lock = threading.Lock()
        self._samples: Dict[Transport, Deque[float]] = defaultdict(
            lambda: deque(maxlen=window_size)
        )

    def record(self, transport: Transport, latency_ms: float) -> None:
        with self._lock:
            self._samples[transport].append(latency_ms)

    def percentiles(self) -> Dict[str, Dict[str, float]]:
        result: Dict[str, Dict[str, float]] = {}
        with self._lock:
            for transport, samples in self._samples.items():
                if not samples:
                    continue
                sorted_samples = sorted(samples)
                n = len(sorted_samples)
                p50 = sorted_samples[int(n * 0.50)]
                p95 = sorted_samples[int(min(n - 1, n * 0.95))]
                result[transport.value] = {
                    "count": n,
                    "p50_ms": round(p50, 2),
                    "p95_ms": round(p95, 2),
                    "min_ms": round(sorted_samples[0], 2),
                    "max_ms": round(sorted_samples[-1], 2),
                    "avg_ms": round(statistics.mean(sorted_samples), 2),
                }
        return result

    def render_ascii_chart(self) -> str:
        """Egyszerű ASCII oszlopdiagram P50 és P95 értékekkel."""
        stats = self.percentiles()
        if not stats:
            return "  (nincs még latencia-mérés)"
        max_val = max(
            s["p95_ms"] for s in stats.values()
        ) or 1.0
        lines: List[str] = []
        for transport, s in sorted(stats.items()):
            p50_bar = "█" * int((s["p50_ms"] / max_val) * 40)
            p95_bar = "▓" * int((s["p95_ms"] / max_val) * 40)
            lines.append(
                f"  {transport:12s} P50 {s['p50_ms']:7.2f}ms {p50_bar}"
            )
            lines.append(
                f"  {'':12s} P95 {s['p95_ms']:7.2f}ms {p95_bar}"
            )
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# 3.  Dead Letter Queue
# ---------------------------------------------------------------------------

class DeadLetterQueue:
    """Sikertelen task-ok tárolása és újrapróbálási lehetőséggel."""

    def __init__(self, max_size: int = 1000) -> None:
        self._max_size = max_size
        self._lock = threading.Lock()
        self._items: Dict[str, DeadLetter] = {}

    def push(
        self,
        task_name: str,
        target_node: str,
        payload: Dict[str, Any],
        error: str,
        attempts: int,
    ) -> DeadLetter:
        dl_id = str(uuid.uuid4())
        dl = DeadLetter(
            id=dl_id,
            task_name=task_name,
            target_node=target_node,
            payload=payload,
            error=error,
            attempts=attempts,
        )
        with self._lock:
            if len(self._items) >= self._max_size:
                oldest = min(self._items.values(), key=lambda d: d.created_at)
                del self._items[oldest.id]
            self._items[dl_id] = dl
        logger.warning(
            "DLQ +1: task=%s target=%s error=%s attempts=%d",
            task_name, target_node, error, attempts,
        )
        return dl

    def pop(self, dl_id: str) -> Optional[DeadLetter]:
        with self._lock:
            return self._items.pop(dl_id, None)

    def list_all(self) -> List[DeadLetter]:
        with self._lock:
            return list(self._items.values())

    def size(self) -> int:
        with self._lock:
            return len(self._items)

    def render_panel(self) -> str:
        items = self.list_all()
        if not items:
            return "  DLQ üres ✓"
        lines = [f"  DLQ — {len(items)} elem:"]
        for dl in items[:20]:
            age = time.time() - dl.created_at
            lines.append(
                f"    [{dl.id[:8]}] task={dl.task_name} "
                f"target={dl.target_node} attempts={dl.attempts} "
                f"age={age:.0f}s error={dl.error[:60]}"
            )
        if len(items) > 20:
            lines.append(f"    ... és még {len(items) - 20} elem")
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# 4.  Capability Registry + Skill Sync
# ---------------------------------------------------------------------------

class CapabilityRegistry:
    """
    Központi képesség-regisztrum.
    Minden node hirdeti a skilljeit ide; a delegation innen választ.
    """

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._nodes: Dict[str, MeshNode] = {}
        # skill_name -> set(node_id)  (gyors lookup)
        self._skill_index: Dict[str, Set[str]] = defaultdict(set)
        # skill sync callback-ek
        self._sync_callbacks: List[Callable[[str, Capability], None]] = []

    # -- Node management ------------------------------------------------
    def register_node(self, node: MeshNode) -> None:
        with self._lock:
            self._nodes[node.node_id] = node
            for cap in node.capabilities:
                self._skill_index[cap.name].add(node.node_id)
        logger.info("Node regisztrálva: %s (%s)", node.node_id, node.name)

    def deregister_node(self, node_id: str) -> None:
        with self._lock:
            node = self._nodes.pop(node_id, None)
            if node:
                for cap in node.capabilities:
                    self._skill_index[cap.name].discard(node_id)
                    if not self._skill_index[cap.name]:
                        del self._skill_index[cap.name]

    def heartbeat(self, node_id: str) -> None:
        with self._lock:
            if node_id in self._nodes:
                self._nodes[node_id].last_heartbeat = time.time()
                self._nodes[node_id].online = True

    def get_node(self, node_id: str) -> Optional[MeshNode]:
        with self._lock:
            return self._nodes.get(node_id)

    def all_nodes(self) -> List[MeshNode]:
        with self._lock:
            return list(self._nodes.values())

    def online_nodes(self) -> List[MeshNode]:
        with self._lock:
            return [n for n in self._nodes.values() if n.online]

    # -- Capability management -----------------------------------------
    def advertise_capability(self, node_id: str, cap: Capability) -> None:
        """Node hirdet egy skillt (vagy frissíti)."""
        with self._lock:
            node = self._nodes.get(node_id)
            if not node:
                raise KeyError(f"Node {node_id} nincs regisztrálva")
            node.add_capability(cap)
            self._skill_index[cap.name].add(node_id)
        # Skill sync: értesítjük a callback-eket
        for cb in self._sync_callbacks:
            try:
                cb(node_id, cap)
            except Exception as exc:
                logger.error("Skill-sync callback hiba: %s", exc)

    def learn_skill(self, node_id: str, cap: Capability) -> None:
        """
        Agent új skillt tanul → advertise + sync peer-eknek.
        Ez a 'Skill-sync' ötlet implementációja.
        """
        logger.info(
            "Skill-sync: node %s megtanulta: %s", node_id, cap.name
        )
        self.advertise_capability(node_id, cap)

    def register_sync_callback(
        self, cb: Callable[[str, Capability], None]
    ) -> None:
        self._sync_callbacks.append(cb)

    def withdraw_capability(self, node_id: str, skill_name: str) -> None:
        with self._lock:
            node = self._nodes.get(node_id)
            if node:
                node.remove_capability(skill_name)
                self._skill_index[skill_name].discard(node_id)
                if not self._skill_index[skill_name]:
                    del self._skill_index[skill_name]

    # -- Query ----------------------------------------------------------
    def find_nodes_for_skill(self, skill_name: str) -> List[MeshNode]:
        with self._lock:
            node_ids = self._skill_index.get(skill_name, set())
            return [
                self._nodes[nid]
                for nid in node_ids
                if nid in self._nodes and self._nodes[nid].online
            ]

    def all_capabilities(self) -> Dict[str, List[str]]:
        """skill_name -> [node_id, ...]"""
        with self._lock:
            return {
                skill: sorted(node_ids)
                for skill, node_ids in self._skill_index.items()
            }


# ---------------------------------------------------------------------------
# 5.  Delegation Router — a legalkalmasabb agentnek route-ol
# ---------------------------------------------------------------------------

class DelegationRouter:
    """
    Score-alapú delegation: nem körbe küldi, hanem a legalkalmasabb
    agentnek adja a task-ot.

    Score = confidence * (1 / (1 + cost)) * load_penalty * recency_bonus
    """

    def __init__(
        self,
        registry: CapabilityRegistry,
        latency_tracker: LatencyTracker,
        dlq: DeadLetterQueue,
        max_retries: int = 3,
    ) -> None:
        self.registry = registry
        self.latency_tracker = latency_tracker
        self.dlq = dlq
        self.max_retries = max_retries
        self._lock = threading.Lock()
        # node_id -> aktuális terhelés (futó task-ok száma)
        self._load: Dict[str, int] = defaultdict(int)
        # node_id -> utolsó sikeres végrehajtás ideje
        self._last_success: Dict[str, float] = {}

    # -- Scoring --------------------------------------------------------
    def _score_node(self, node: MeshNode, cap: Capability) -> float:
        load = self._load[node.node_id]
        load_penalty = 1.0 / (1.0 + load * 0.3)
        now = time.time()
        recency = now - self._last_success.get(node.node_id, 0)
        recency_bonus = 1.0 + max(0.0, 300.0 - recency) / 300.0 * 0.1
        cost_factor = 1.0 / (1.0 + cap.cost)
        score = cap.confidence * cost_factor * load_penalty * recency_bonus
        return score

    def select_best_node(
        self, skill_name: str, exclude: Optional[Set[str]] = None
    ) -> Tuple[Optional[MeshNode], Optional[Capability]]:
        """Visszaadja a legjobban scored node-ot a skill-hez."""
        candidates = self.registry.find_nodes_for_skill(skill_name)
        if exclude:
            candidates = [n for n in candidates if n.node_id not in exclude]
        if not candidates:
            return None, None

        best_node: Optional[MeshNode] = None
        best_cap: Optional[Capability] = None
        best_score = -1.0
        for node in candidates:
            cap = node.get_capability(skill_name)
            if cap is None:
                continue
            score = self._score_node(node, cap)
            if score > best_score:
                best_score = score
                best_node = node
                best_cap = cap
        return best_node, best_cap

    def rank_nodes(
        self, skill_name: str
    ) -> List[Tuple[MeshNode, Capability, float]]:
        """Minden jelölt node score-szal."""
        candidates = self.registry.find_nodes_for_skill(skill_name)
        ranked: List[Tuple[MeshNode, Capability, float]] = []
        for node in candidates:
            cap = node.get_capability(skill_name)
            if cap is None:
                continue
            ranked.append((node, cap, self._score_node(node, cap)))
        ranked.sort(key=lambda x: x[2], reverse=True)
        return ranked

    # -- Delegation -----------------------------------------------------
    def delegate(
        self,
        skill_name: str,
        payload: Dict[str, Any],
        transport: Transport = Transport.INPROCESS,
        handler_map: Optional[Dict[str, Callable[..., Any]]] = None,
    ) -> Dict[str, Any]:
        """
        Delegál egy task-ot a legalkalmasabb agentnek.
        Ha az elsődleges node nem elérhető / hibázik, fallback a következőre.
        Ha mindenki elbukik → DLQ-ba kerül.
        """
        handler_map = handler_map or {}
        tried: Set[str] = set()
        last_error = ""

        for attempt in range(1, self.max_retries + 1):
            node, cap = self.select_best_node(skill_name, exclude=tried)
            if node is None:
                break

            tried.add(node.node_id)
            logger.info(
                "Delegation: skill=%s → node=%s (attempt %d/%d, score alapján)",
                skill_name, node.node_id, attempt, self.max_retries,
            )

            with self._lock:
                self._load[node.node_id] += 1

            start = time.time()
            try:
                result = self._execute(
                    node, cap, skill_name, payload, handler_map
                )
                elapsed_ms = (time.time() - start) * 1000.0
                self.latency_tracker.record(transport, elapsed_ms)
                self._last_success[node.node_id] = time.time()
                return {
                    "status": "ok",
                    "node_id": node.node_id,
                    "node_name": node.name,
                    "skill": skill_name,
                    "capability_version": cap.version,
                    "latency_ms": round(elapsed_ms, 2),
                    "transport": transport.value,
                    "result": result,
                    "attempts": attempt,
                }
            except Exception as exc:
                elapsed_ms = (time.time() - start) * 1000.0
                self.latency_tracker.record(transport, elapsed_ms)
                last_error = str(exc)
                logger.warning(
                    "Delegation sikertelen: node=%s error=%s",
                    node.node_id, last_error,
                )
            finally:
                with self._lock:
                    self._load[node.node_id] -= 1

        # Minden próbálkozás elbukott → DLQ
        self.dlq.push(
            task_name=skill_name,
            target_node=",".join(sorted(tried)) or "none",
            payload=payload,
            error=last_error,
            attempts=len(tried),
        )
        return {
            "status": "failed",
            "skill": skill_name,
            "error": last_error,
            "tried_nodes": sorted(tried),
            "attempts": len(tried),
            "dlq": True,
        }

    def _execute(
        self,
        node: MeshNode,
        cap: Capability,
        skill_name: str,
        payload: Dict[str, Any],
        handler_map: Dict[str, Callable[..., Any]],
    ) -> Any:
        """
        Tényleges végrehajtás.
        Ha a handler_map tartalmazza a node_id-t, azt hívja;
        egyébként a beépített demo handler-t.
        """
        handler = handler_map.get(node.node_id)
        if handler:
            return handler(skill_name, payload)
        # Demo handler: egyszerű echo + számítás
        if skill_name == "math.add":
            return {"sum": payload.get("a", 0) + payload.get("b", 0)}
        if skill_name == "math.multiply":
            return {"product": payload.get("a", 0) * payload.get("b", 0)}
        if skill_name == "text.uppercase":
            return {"result": str(payload.get("text", "")).upper()}
        if skill_name == "text.reverse":
            return {"result": str(payload.get("text", ""))[::-1]}
        if skill_name == "json.validate":
            try:
                json.loads(payload.get("raw", "{}"))
                return {"valid": True}
            except json.JSONDecodeError as e:
                return {"valid": False, "error": str(e)}
        if skill_name == "sleep":
            time.sleep(payload.get("seconds", 0.1))
            return {"slept": payload.get("seconds", 0.1)}
        # Ismeretlen skill de regisztrálva van → hiba
        raise RuntimeError(
            f"Nincs handler a skill-hez '{skill_name}' a node-on {node.node_id}"
        )


# ---------------------------------------------------------------------------
# 6.  Mesh Manager — összeköti a komponenseket
# ---------------------------------------------------------------------------

class MeshManager:
    """Felső szintű orchestrator."""

    def __init__(self) -> None:
        self.registry = CapabilityRegistry()
        self.latency = LatencyTracker()
        self.dlq = DeadLetterQueue()
        self.router = DelegationRouter(self.registry, self.latency, self.dlq)

        # Skill-sync: ha egy node tanul, logoljuk
        self.registry.register_sync_callback(self._on_skill_sync)

    def _on_skill_sync(self, node_id: str, cap: Capability) -> None:
        logger.info(
            "[Skill-sync] Node %s skill-t hirdet: %s v%s — peer-ek értesítve",
            node_id, cap.name, cap.version,
        )

    def add_node(self, node: MeshNode) -> None:
        self.registry.register_node(node)

    def remove_node(self, node_id: str) -> None:
        self.registry.deregister_node(node_id)

    def delegate(
        self,
        skill_name: str,
        payload: Dict[str, Any],
        transport: Transport = Transport.INPROCESS,
        handler_map: Optional[Dict[str, Callable[..., Any]]] = None,
    ) -> Dict[str, Any]:
        return self.router.delegate(skill_name, payload, transport, handler_map)

    def dashboard(self) -> str:
        """Szöveges dashboard: node-ok, skill-ek, latencia, DLQ."""
        lines: List[str] = []
        lines.append("=" * 70)
        lines.append("  A2A MESH DASHBOARD")
        lines.append("=" * 70)

        # Nodes
        nodes = self.registry.all_nodes()
        lines.append(f"\n  NODES ({len(nodes)}):")
        for n in nodes:
            skills = ", ".join(n.capability_names()) or "(nincs skill)"
            status = "online" if n.online else "OFFLINE"
            lines.append(
                f"    {n.node_id[:12]:12s} {n.name:20s} "
                f"[{status}] skills: {skills}"
            )

        # Capabilities index
        caps = self.registry.all_capabilities()
        lines.append(f"\n  CAPABILITY INDEX ({len(caps)} skill):")
        for skill, node_ids in sorted(caps.items()):
            lines.append(f"    {skill:25s} → {', '.join(nid[:8] for nid in node_ids)}")

        # Latency
        lines.append("\n  LATENCY (P50/P95 transportonként):")
        lines.append(self.latency.render_ascii_chart())

        # DLQ
        lines.append("\n  DEAD LETTER QUEUE:")
        lines.append(self.dlq.render_panel())

        lines.append("\n" + "=" * 70)
        return "\n".join(lines)


