def build_demo_mesh() -> MeshManager:
    """Felépít egy demo mesh-t több node-dal és skill-lel."""
    mesh = MeshManager()

    # Node 1 — matematikai agent
    n1 = MeshNode(
        node_id="node-math-alpha",
        name="math-alpha",
        address="inprocess://math-alpha",
        capabilities=[
            Capability("math.add", confidence=0.95, cost=0.5, tags=["math", "arithmetic"]),
            Capability("math.multiply", confidence=0.90, cost=0.7, tags=["math"]),
        ],
    )

    # Node 2 — másik matematikai agent (alacsonyabb confidence, olcsóbb)
    n2 = MeshNode(
        node_id="node-math-beta",
        name="math-beta",
        address="inprocess://math-beta",
        capabilities=[
            Capability("math.add", confidence=0.80, cost=0.3, tags=["math"]),
            Capability("math.multiply", confidence=0.85, cost=0.4, tags=["math"]),
        ],
    )

    # Node 3 — szöveg agent
    n3 = MeshNode(
        node_id="node-text-gamma",
        name="text-gamma",
        address="inprocess://text-gamma",
        capabilities=[
            Capability("text.uppercase", confidence=1.0, cost=0.2, tags=["text"]),
            Capability("text.reverse", confidence=0.95, cost=0.2, tags=["text"]),
        ],
    )

    # Node 4 — JSON validátor
    n4 = MeshNode(
        node_id="node-json-delta",
        name="json-delta",
        address="inprocess://json-delta",
        capabilities=[
            Capability("json.validate", confidence=0.99, cost=0.1, tags=["json", "validation"]),
        ],
    )

    for n in (n1, n2, n3, n4):
        mesh.add_node(n)

    return mesh


def run_demo() -> None:
    print()
    print("╔══════════════════════════════════════════════════════════╗")
    print("║  A2A Mesh — Képesség-regisztráció & Delegation Demo     ║")
    print("║  Generated by runa via A2A Mesh delegation               ║")
    print("╚══════════════════════════════════════════════════════════╝")
    print()

    mesh = build_demo_mesh()

    # --- 1. Alap delegation tesztek -------------------------------------
    print(">>> 1. Delegation tesztek (legalkalmasabb agentnek route-ol):\n")

    tasks = [
        ("math.add", {"a": 10, "b": 32}, Transport.INPROCESS),
        ("math.multiply", {"a": 7, "b": 6}, Transport.HTTP),
        ("text.uppercase", {"text": "hello mesh"}, Transport.WEBSOCKET),
        ("text.reverse", {"text": "dlrow olleh"}, Transport.GRPC),
        ("json.validate", {"raw": '{"key": "value"}'}, Transport.HTTP),
        ("json.validate", {"raw": "{invalid json}"}, Transport.HTTP),
    ]

    for skill, payload, transport in tasks:
        result = mesh.delegate(skill, payload, transport)
        status_icon = "✓" if result["status"] == "ok" else "✗"
        node_info = result.get("node_name", result.get("tried_nodes", "?"))
        latency = result.get("latency_ms", "—")
        print(
            f"  {status_icon} {skill:20s} → {node_info} "
            f"[{transport.value}] {latency}ms  result={result.get('result', result.get('error'))}"
        )

    # --- 2. Több hívás → latencia adatok --------------------------------
    print("\n>>> 2. Terhelés: 50 task különböző transportokon...\n")
    for i in range(50):
        t = Transport(list(Transport)[i % len(Transport)])
        mesh.delegate("math.add", {"a": i, "b": i + 1}, t)
    for i in range(30):
        mesh.delegate("text.uppercase", {"text": f"test{i}"}, Transport.WEBSOCKET)
    for i in range(20):
        mesh.delegate("json.validate", {"raw": '{"i": %d}' % i}, Transport.GRPC)

    # --- 3. Skill-sync demo ---------------------------------------------
    print("\n>>> 3. Skill-sync: egy agent új skillt tanul...\n")
    mesh.registry.learn_skill(
        "node-text-gamma",
        Capability(
            "text.lowercase",
            version="1.0.0",
            description="Kisbetűsítés",
            confidence=0.92,
            cost=0.2,
            tags=["text"],
        ),
    )
    # Most már delegálható az új skill
    result = mesh.delegate("text.lowercase", {"text": "MAKE ME SMALL"}, Transport.INPROCESS)
    print(f"  ✓ text.lowercase → {result.get('node_name')} result={result.get('result')}")

    # --- 4. DLQ teszt — nem létező skill --------------------------------
    print("\n>>> 4. DLQ teszt: nem létező skill delegation...\n")
    result = mesh.delegate("nonexistent.skill", {"data": 42}, Transport.HTTP)
    print(f"  ✗ nonexistent.skill → status={result['status']} dlq={result.get('dlq')}")

    # --- 5. Ranking mutatása --------------------------------------------
    print("\n>>> 5. Node ranking a 'math.add' skill-hez:\n")
    ranked = mesh.router.rank_nodes("math.add")
    for node, cap, score in ranked:
        print(
            f"    {node.node_id:20s} score={score:.4f}  "
            f"confidence={cap.confidence} cost={cap.cost} load={mesh.router._load[node.node_id]}"
        )

    # --- 6. Dashboard ---------------------------------------------------
    print()
    print(mesh.dashboard())


if __name__ == "__main__":
    run_demo()